question.solution:
def to_postfix(expr):
    prec = {'+': 1, '-': 1, '*': 2, '/': 2}
    out = []
    ops = []
    for ch in expr:
        if ch.isalnum():
            out.append(ch)
        elif ch == '(':
            ops.append(ch)
        elif ch == ')':
            while ops and ops[-1] != '(':
                out.append(ops.pop())
            if ops:
                ops.pop()
        elif ch in prec:
            while ops and ops[-1] != '(' and prec[ops[-1]] >= prec[ch]:
                out.append(ops.pop())
            ops.append(ch)
    while ops:
        out.append(ops.pop())
    return ' '.join(out)

print(to_postfix('3+4*5'))
print(to_postfix('(3+4)*5'))
print(to_postfix('a+b*c-d'))
print(repr(to_postfix('')))
